<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Usecase\List;

use Psr\EventDispatcher\EventDispatcherInterface;
use Throwable;
use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Application\Service\Visibility\UserFederatedIdentityVisibilityService;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityQueryRepositoryGateway;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityFilter;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityCursor;
use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\Gateway\UserFederatedIdentityAttributesSlide;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class UserFederatedIdentityListUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly EventDispatcherInterface $dispatcher,
        private readonly UserFederatedIdentityVisibilityService $visibility,
        private readonly UserFederatedIdentityQueryRepositoryGateway $reader
    ) {
    }

    public function allowList(): Allow
    {
        $this->logDebug("Check allow of list usecase for User federated identity");
        $span = $this->startSpan("Check allow of list usecase for User federated identity");
        try {
            $result = $this->dispatcher->dispatch(new UserFederatedIdentityListAllowDecision(Allow::allowed('list', 'Allowed to list by default')));
            return $result->getAllow();
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function count(UserFederatedIdentityFilter $filter): int
    {
        $this->logDebug("Run list usecase for User federated identity");
        $span = $this->startSpan("Run list usecase for User federated identity");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list User federated identity');
            }
            return $this->visibility->countVisibles($filter);
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
    public function list(UserFederatedIdentityFilter $filter, ?UserFederatedIdentityCursor $cursor = null): UserFederatedIdentityAttributesSlide
    {
        $this->logDebug("Run list usecase for User federated identity");
        $span = $this->startSpan("Run list usecase for User federated identity");
        try {
            $allow = $this->allowList();
            if (!$allow->allowed) {
                throw new UnauthorizedException($allow->reason ?? 'Not allowed to list');
            }
            $slide = $this->visibility->listVisibles($filter, $cursor);
            return new UserFederatedIdentityAttributesSlide($slide->nextCursor(), array_map(fn ($item) => $this->visibility->copyWithHidden($this->visibility->prepareVisibleData($item)), $slide->values()), $slide->hasNext());
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
